+function setupRequestSignal (reply) {
+  let request = reply.request
+  const req = request.raw
+  const res = reply.raw
+
+  // HTTP/2 can emit finish when a stream closes before its response is written.
+  const onFinish = () => {
+    const cleanup = request?.[kOnAbort]
+    // Keep Request out of the lazy abort stack's receiver.
+    cleanup?.(req.aborted === true || (req.httpVersionMajor === 2 && res.writableFinished === false))
+  }
+  request[kOnAbort] = function cleanup (abort = true) {
+    if (request === null) return
+    const current = request
+    // Release the closed-over request before capturing the abort stack.
+    request = null
+    current[kOnAbort] = null
+    res.removeListener('finish', onFinish)
+    res.removeListener('close', cleanup)
+
+    let ac = current[kRequestSignal]
+    if (abort && !ac) {
+      ac = new AbortController()
+      current[kRequestSignal] = ac
+    }
+    if (ac) {
+      clearTimeout(current[kTimeoutTimer])
+      current[kTimeoutTimer] = null
+      if (abort && !ac.signal.aborted) {
+        ac.abort()
+      }
+    }
+  }
+  res.on('finish', onFinish)
+  res.on('close', request[kOnAbort])
+}
